{% if product.metafields.custom.design %}
  <div style="
    display: inline-block;
    position: relative; /* for shimmer overlay */
    background-image: url('https://cdn.shopify.com/s/files/1/0943/5643/9325/files/d449304654172ab89627e617b8cfe3db.jpg?v=1760295996');
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    color: #00000;
    font-weight: 600;
    padding: 6px 14px;
    border-radius: 20px;
    box-shadow: 0 0 0, 0 0 8px rgba(255, 215, 0, 0.3);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    width: fit-content;
    overflow: hidden;
  ">
    {{ product.metafields.custom.design }}
    <div style="
      position: absolute;
      top: 0; left: -75%;
      width: 50%;
      height: 100%;
      background: linear-gradient(120deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.4) 50%, rgba(255,255,255,0) 100%);
      transform: skewX(-20deg);
      animation: shimmer 2s infinite;
    "></div>

    <style>
      @keyframes shimmer {
        0% { left: -75%; }
        100% { left: 125%; }
      }
    </style>
  </div>
{% endif %}

