{% if product.tags contains 'pod' %}

<style>
  .pod-wrapper {
    border: 1px solid #eee;
    border-radius: 8px;
    overflow: hidden;
    margin: 16px 0;
    font-family: inherit;
  }

  .pod-header {
    background: #f9758d;
    color: #fff;
    padding: 12px 16px;
    font-weight: 600;
    font-size: 16px;
  }

  .pod-body {
    padding: 16px;
    background: #fff;
  }

  .pod-field {
    margin-bottom: 14px;
  }

  .pod-field label {
    display: block;
    font-size: 13px;
    font-weight: 500;
    color: #000;
    margin-bottom: 6px;
  }

  .pod-field input[type="file"],
  .pod-field textarea {
    width: 100%;
    padding: 10px;
    border-radius: 6px;
    font-size: 13px;
  }

  .pod-field input[type="file"] {
    border: 1px dashed #ccc;
    cursor: pointer;
    background: #fafafa;
  }

  .pod-field textarea {
    min-height: 80px;
    border: 1px solid #ddd;
    resize: vertical;
  }

  .pod-note {
    font-size: 10px;
    color: #777;
    margin-top: 6px;
  }

  .fake-submit {
    width: 100%;
    margin-top: 10px;
    padding: 12px;
    background: #f9758d;
    color: #fff;
    border-radius: 6px;
    font-size: 14px;
    text-align: center;
    cursor: pointer;
  }

  .upload-success {
    display: none;
    padding: 16px;
    text-align: center;
  }

  .upload-success p {
    font-size: 14px;
    margin-bottom: 12px;
  }

  .reupload-btn {
    font-size: 13px;
    color: #f9758d;
    cursor: pointer;
    text-decoration: underline;
  }
</style>

{% form 'product', product, enctype: 'multipart/form-data' %}

<div class="pod-wrapper">

  <div class="pod-header">
    Upload your image
  </div>

  <div class="pod-body" id="podForm">

    <div class="pod-field">
      <label>Select your image</label>
      <input type="file" id="podImage" name="properties[Keychain Image]" accept="image/*" required>
      <div class="pod-note">
        JPG, PNG or JPEG • High quality recommended
      </div>
    </div>

    <div class="pod-field">
      <label>Any instructions?</label>
      <textarea name="properties[Instructions]"></textarea>
    </div>

    <div class="fake-submit" onclick="confirmUpload()">
      Submit
    </div>

  </div>

  <div class="upload-success" id="uploadSuccess">
    <p><strong>Image(s) are uploaded, now please proceed with your order.</strong></p>
    <span class="reupload-btn" onclick="reUpload()">Re-upload image</span>
  </div>

</div>

{% endform %}

<script>
  function confirmUpload() {
    const imageInput = document.getElementById('podImage');
    if (!imageInput.files.length) {
      alert('Please select an image first.');
      return;
    }
    document.getElementById('podForm').style.display = 'none';
    document.getElementById('uploadSuccess').style.display = 'block';
  }

  function reUpload() {
    document.getElementById('podForm').style.display = 'block';
    document.getElementById('uploadSuccess').style.display = 'none';
    document.getElementById('podImage').value = '';
  }
</script>

{% endif %}
